mapper.select:
SELECT s.session_id, s.summary_text, s.message_count, s.updated_at, s.agent_id, s.team_id,
       (SELECT NULLIF(LEFT(TRIM(regexp_replace(m.content, '[[:space:]]+', ' ', 'g')), 80), '')
        FROM nw_chat_messages m
        WHERE m.tenant_id = s.tenant_id AND m.session_id = s.session_id AND m.role = 'user'
          AND m.metadata -> 'context_only' IS DISTINCT FROM 'true'::jsonb
        ORDER BY m.created_at, m.id LIMIT 1) AS title
FROM nw_chat_sessions s
WHERE s.tenant_id = #{tenantId}
  AND s.group_binding_id IS NULL
  AND NOT EXISTS(SELECT 1 FROM nw_workflow_test_sessions wt WHERE wt.tenant_id=s.tenant_id AND wt.session_id=s.session_id)
AND s.end_user_id = #{endUserId}
AND s.agent_id = #{agentId}
AND s.team_id = #{teamId}
AND s.channel_id = #{channelId}



            AND s.session_id IN
            #{visibleSessionId}

        AND FALSE


ORDER BY (SELECT MAX(m.created_at) FROM nw_chat_messages m
          WHERE m.tenant_id = s.tenant_id AND m.session_id = s.session_id) DESC NULLS LAST,
         s.created_at DESC, s.id DESC
